//! Writes `mc-bindings/src/generated.rs` and `mc-versions/src/supported.rs`.
//! Each spec class becomes a handle (derefs to its superclass), a Rust enum or
//! a value struct.

use std::collections::HashMap;
use std::fmt::Write as _;

use crate::resolve::{snake_case, ApiClass, ApiMember, Binding, ClassKind, Kind, Model};

const HEADER: &str =
    "// @generated by `cargo xtask bindgen` from `mc-data/` — do not edit by hand.\n";

#[derive(Debug, Clone, PartialEq, Eq)]
enum JType {
    Prim(char),
    Class(String),
    Array,
}

fn parse_types(descriptor: &str) -> Vec<JType> {
    let mut out = Vec::new();
    let mut chars = descriptor.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '[' => {
                while chars.peek() == Some(&'[') {
                    chars.next();
                }
                if chars.next() == Some('L') {
                    for end in chars.by_ref() {
                        if end == ';' {
                            break;
                        }
                    }
                }
                out.push(JType::Array);
            }
            'L' => {
                let name: String = chars.by_ref().take_while(|&c| c != ';').collect();
                out.push(JType::Class(name));
            }
            other => out.push(JType::Prim(other)),
        }
    }
    out
}

/// `Prim('V')` for a void return.
fn method_types(descriptor: &str) -> (Vec<JType>, JType) {
    let (params, ret) = descriptor
        .strip_prefix('(')
        .and_then(|rest| rest.split_once(')'))
        .unwrap_or(("", descriptor));
    let ret = parse_types(ret).pop().unwrap_or(JType::Prim('V'));
    (parse_types(params), ret)
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum RType {
    Prim(char),
    Handle(String),
    Object,
    Str,
    Enum(String),
    Value(String),
}

impl RType {
    fn param(&self) -> String {
        match self {
            RType::Prim(c) => prim(*c).to_string(),
            RType::Handle(name) => format!("&{name}"),
            RType::Object => "&Object".to_string(),
            RType::Str => "&str".to_string(),
            RType::Enum(name) | RType::Value(name) => name.clone(),
        }
    }

    fn result(&self) -> String {
        match self {
            RType::Prim(c) => prim(*c).to_string(),
            RType::Handle(name) | RType::Enum(name) | RType::Value(name) => name.clone(),
            RType::Object => "Object".to_string(),
            RType::Str => "String".to_string(),
        }
    }

    fn param_name(&self) -> String {
        match self {
            RType::Prim(_) => "value".to_string(),
            RType::Handle(name) | RType::Enum(name) | RType::Value(name) => snake_case(name),
            RType::Object => "object".to_string(),
            RType::Str => "text".to_string(),
        }
    }
}

fn prim(c: char) -> &'static str {
    match c {
        'Z' => "bool",
        'B' => "i8",
        'C' => "u16",
        'S' => "i16",
        'I' => "i32",
        'J' => "i64",
        'F' => "f32",
        'D' => "f64",
        _ => "()",
    }
}

fn accessor(c: char) -> &'static str {
    match c {
        'Z' => "z",
        'B' => "b",
        'C' => "c",
        'S' => "s",
        'I' => "i",
        'J' => "j",
        'F' => "f",
        'D' => "d",
        _ => "v",
    }
}

fn return_type_const(ret: &JType) -> &'static str {
    match ret {
        JType::Prim('Z') => "ReturnType::Primitive(Primitive::Boolean)",
        JType::Prim('B') => "ReturnType::Primitive(Primitive::Byte)",
        JType::Prim('C') => "ReturnType::Primitive(Primitive::Char)",
        JType::Prim('S') => "ReturnType::Primitive(Primitive::Short)",
        JType::Prim('I') => "ReturnType::Primitive(Primitive::Int)",
        JType::Prim('J') => "ReturnType::Primitive(Primitive::Long)",
        JType::Prim('F') => "ReturnType::Primitive(Primitive::Float)",
        JType::Prim('D') => "ReturnType::Primitive(Primitive::Double)",
        JType::Prim(_) => "ReturnType::Primitive(Primitive::Void)",
        JType::Array => "ReturnType::Array",
        JType::Class(_) => "ReturnType::Object",
    }
}

/// Spec classes by newest JNI name.
struct Types<'m> {
    classes: HashMap<&'m str, &'m ApiClass>,
}

impl<'m> Types<'m> {
    fn new(model: &'m Model) -> Types<'m> {
        Types {
            classes: model
                .classes
                .iter()
                .map(|class| (class.name.as_str(), class))
                .collect(),
        }
    }

    /// A `CharSequence` parameter takes a string.
    fn param_rtype(&self, ty: &JType) -> RType {
        match ty {
            JType::Class(name) if name == "java/lang/CharSequence" => RType::Str,
            _ => self.rtype(ty),
        }
    }

    fn rtype(&self, ty: &JType) -> RType {
        match ty {
            JType::Prim(c) => RType::Prim(*c),
            JType::Array => RType::Object,
            JType::Class(name) if name == "java/lang/String" => RType::Str,
            JType::Class(name) => match self.classes.get(name.as_str()) {
                Some(class) => match class.kind {
                    ClassKind::Handle => RType::Handle(class.rust.clone()),
                    ClassKind::Enum(_) => RType::Enum(class.rust.clone()),
                    ClassKind::Value(_) => RType::Value(class.rust.clone()),
                },
                None => RType::Object,
            },
        }
    }
}

fn group_versions(model: &Model, group: usize) -> String {
    model
        .versions
        .iter()
        .zip(&model.groups)
        .filter(|(_, g)| **g == group)
        .map(|((id, _), _)| id.as_str())
        .collect::<Vec<_>>()
        .join(", ")
}

/// One value per group (its first version stands for it), equal values merged.
fn arms<T: Clone + PartialEq>(model: &Model, per_version: &[T]) -> Vec<(Vec<usize>, T)> {
    let mut arms: Vec<(Vec<usize>, T)> = Vec::new();
    for group in 0..model.group_count {
        let first = model.groups.iter().position(|g| *g == group).unwrap();
        let value = per_version[first].clone();
        match arms.iter_mut().find(|(_, other)| *other == value) {
            Some((groups, _)) => groups.push(group),
            None => arms.push((vec![group], value)),
        }
    }
    arms
}

/// The last arm is the catch-all.
fn dispatch(arms: &[(Vec<usize>, String)]) -> String {
    if arms.len() == 1 {
        return arms[0].1.clone();
    }
    let mut out = String::from("match crate::group()? {\n");
    for (index, (groups, body)) in arms.iter().enumerate() {
        let pattern = if index + 1 == arms.len() {
            "_".to_string()
        } else {
            groups
                .iter()
                .map(usize::to_string)
                .collect::<Vec<_>>()
                .join(" | ")
        };
        let _ = writeln!(out, "{pattern} => {body},");
    }
    out.push('}');
    out
}

/// Declares the member's targets as statics and binds the running one to
/// `target`. Returns false when every arm returns early (shim or unavailable).
fn emit_target(
    out: &mut String,
    model: &Model,
    member: &ApiMember,
    label: &str,
    field: bool,
    shim: Option<&dyn Fn(&str) -> String>,
) -> Result<bool, String> {
    let mut statics: Vec<&Binding> = Vec::new();
    for binding in &member.bindings {
        if matches!(binding, Binding::Direct { .. }) && !statics.contains(&binding) {
            statics.push(binding);
        }
    }
    for (index, binding) in statics.iter().enumerate() {
        let Binding::Direct {
            class,
            name,
            descriptor,
            is_static,
            ..
        } = binding
        else {
            unreachable!()
        };
        if field {
            let _ = writeln!(
                out,
                "static T{index}: Field = Field::new({class:?}, {name:?}, {descriptor:?}, {is_static});"
            );
        } else {
            let ret = method_types(descriptor).1;
            let _ = writeln!(
                out,
                "static T{index}: Method = Method::new({class:?}, {name:?}, {descriptor:?}, {is_static}, {});",
                return_type_const(&ret)
            );
        }
    }
    let mut bodies = Vec::new();
    for binding in &member.bindings {
        bodies.push(match binding {
            Binding::Direct { .. } => {
                let index = statics.iter().position(|other| *other == binding).unwrap();
                format!("&T{index}")
            }
            Binding::Shim(function) => match shim {
                Some(call) => format!("return {}", call(function)),
                None => return Err(format!("{label}: cannot be provided by a shim")),
            },
            Binding::Unavailable => format!("return Err(crate::unavailable({label:?}))"),
        });
    }
    let arms = arms(model, &bodies);
    if statics.is_empty() {
        let _ = writeln!(out, "{}", dispatch(&arms));
        return Ok(false);
    }
    let kind = if field { "Field" } else { "Method" };
    let _ = writeln!(out, "let target: &'static {kind} = {};", dispatch(&arms));
    Ok(true)
}

/// Emits any setup the argument needs and returns its `jvalue` expression.
fn argument(out: &mut String, ty: &RType, name: &str, index: usize) -> String {
    match ty {
        RType::Prim(_) => format!("JValue::from({name}).as_jni()"),
        RType::Handle(_) | RType::Object => format!("JValue::Object({name}.as_obj()).as_jni()"),
        RType::Str => {
            let _ = writeln!(out, "let a{index} = cx.new_string({name})?;");
            let _ = writeln!(out, "let a{index} = cx.temp(a{index});");
            format!("a{index}")
        }
        RType::Enum(_) => {
            let _ = writeln!(out, "let a{index} = {name}.constant(cx)?;");
            format!("JValue::Object(a{index}.as_obj()).as_jni()")
        }
        RType::Value(_) => {
            let _ = writeln!(out, "let a{index} = {name}.to_local(cx)?;");
            let _ = writeln!(out, "let a{index} = cx.temp(a{index});");
            format!("a{index}")
        }
    }
}

fn object_result(ty: &RType, object: &str, label: &str, nullable: bool) -> String {
    match ty {
        RType::Handle(name) if nullable => {
            format!("unsafe {{ cx.object_opt::<{name}>({object}) }}")
        }
        RType::Handle(name) => format!("unsafe {{ cx.object::<{name}>({object}, {label:?}) }}"),
        RType::Object if nullable => format!("unsafe {{ cx.object_opt::<Object>({object}) }}"),
        RType::Object => format!("unsafe {{ cx.object::<Object>({object}, {label:?}) }}"),
        RType::Str if nullable => format!("cx.string_opt({object})"),
        RType::Str => format!("cx.string({object}, {label:?})"),
        RType::Enum(name) | RType::Value(name) => {
            let read = if matches!(ty, RType::Enum(_)) {
                "from_java"
            } else {
                "read"
            };
            let (null, some) = if nullable {
                ("Ok(None)".to_string(), ".map(Some)")
            } else {
                (format!("Err(Error::Null {{ member: {label:?} }})"), "")
            };
            format!(
                "{{ let object = {object}; let result = if object.is_null() {{ {null} }} else {{ {name}::{read}(cx, &object){some} }}; cx.delete(object); result }}"
            )
        }
        RType::Prim(_) => unreachable!("not an object"),
    }
}

fn result(
    types: &Types,
    member: &ApiMember,
    ty: &Option<RType>,
    label: &str,
) -> Result<String, String> {
    if let Some(element) = &member.element {
        let element = types.rtype(&JType::Class(element.clone()));
        let is_map = member.descriptor.ends_with("Ljava/util/Map;");
        let convert = match &element {
            RType::Handle(name) => format!("cx.checked::<{name}>(element, {label:?})"),
            RType::Enum(name) | RType::Value(name) => {
                let read = if matches!(element, RType::Enum(_)) {
                    "from_java"
                } else {
                    "read"
                };
                format!(
                    "{{ if element.is_null() {{ return Ok(None); }} let result = {name}::{read}(cx, &element); cx.delete(element); result.map(Some) }}"
                )
            }
            _ => return Err(format!("{label}: `element` must name a spec class")),
        };
        return Ok(format!(
            "cx.collect(value.l()?, {is_map}, |cx, element| {convert})"
        ));
    }
    Ok(match ty {
        None => "Ok(value.v()?)".to_string(),
        Some(RType::Prim(c)) => format!("Ok(value.{}()?)", accessor(*c)),
        Some(ty) => object_result(ty, "value.l()?", label, member.nullable),
    })
}

fn result_type(
    types: &Types,
    member: &ApiMember,
    ty: &Option<RType>,
    label: &str,
) -> Result<String, String> {
    if let Some(element) = &member.element {
        let element = types.rtype(&JType::Class(element.clone()));
        if member.nullable {
            return Err(format!(
                "{label}: a collection is never null; drop `nullable`"
            ));
        }
        if !matches!(ty, Some(RType::Object)) {
            return Err(format!(
                "{label}: `element` needs an Iterable or Map result"
            ));
        }
        return Ok(format!("Vec<{}>", element.result()));
    }
    Ok(match ty {
        None => "()".to_string(),
        Some(RType::Prim(_)) if member.nullable => {
            return Err(format!(
                "{label}: a primitive is never null; drop `nullable`"
            ));
        }
        Some(ty) if member.nullable => format!("Option<{}>", ty.result()),
        Some(ty) => ty.result(),
    })
}

fn member_doc(out: &mut String, model: &Model, class: &ApiClass, member: &ApiMember) {
    // Versions that call the same thing share a line.
    let mut lines: Vec<(Vec<String>, String)> = Vec::new();
    for (groups, binding) in arms(model, &member.bindings) {
        let first = model.groups.iter().position(|g| *g == groups[0]).unwrap();
        let own_class = class.names[first].as_deref().unwrap_or_default();
        let how = match binding {
            Binding::Direct {
                class: owner,
                name,
                descriptor,
                ..
            } => {
                let separator = if member.kind == Kind::Field { ": " } else { "" };
                let owner = if owner == own_class {
                    String::new()
                } else {
                    format!("{owner}.")
                };
                format!("`{owner}{name}{separator}{descriptor}`")
            }
            Binding::Shim(function) => format!("shim `{function}`"),
            Binding::Unavailable => "unavailable".to_string(),
        };
        let versions = groups.iter().map(|group| group_versions(model, *group));
        match lines.iter_mut().find(|(_, other)| *other == how) {
            Some((existing, _)) => existing.extend(versions),
            None => lines.push((versions.collect(), how)),
        }
    }
    if lines.len() > 1 {
        for (versions, how) in lines {
            let _ = writeln!(out, "/// - {}: {how}", versions.join(", "));
        }
    }
}

fn class_doc(out: &mut String, model: &Model, class: &ApiClass) {
    let _ = writeln!(out, "/// `{}`.", class.name);
    let renamed: Vec<String> = arms(model, &class.names)
        .into_iter()
        .filter_map(|(groups, name)| {
            let versions = groups
                .iter()
                .map(|group| group_versions(model, *group))
                .collect::<Vec<_>>()
                .join(", ");
            match name {
                Some(name) if name == class.name => None,
                Some(name) => Some(format!("/// - {versions}: `{name}`")),
                None => Some(format!("/// - {versions}: absent")),
            }
        })
        .collect();
    if !renamed.is_empty() {
        out.push_str("///\n");
        for line in renamed {
            let _ = writeln!(out, "{line}");
        }
    }
}

fn emit_java_type(out: &mut String, model: &Model, class: &ApiClass) {
    let bodies: Vec<String> = class
        .names
        .iter()
        .map(|name| match name {
            Some(name) => format!("Ok({name:?})"),
            None => format!("Err(crate::unavailable({:?}))", class.rust),
        })
        .collect();
    let _ = writeln!(
        out,
        "impl JavaType for {} {{\nfn class_name() -> Result<&'static str> {{\n{}\n}}\n}}\n",
        class.rust,
        dispatch(&arms(model, &bodies))
    );
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Receiver {
    Handle,
    Enum,
    None,
}

impl Receiver {
    fn param(self) -> &'static str {
        match self {
            Receiver::Handle => "&self",
            Receiver::Enum => "self",
            Receiver::None => "",
        }
    }

    fn object(self, out: &mut String) -> &'static str {
        match self {
            Receiver::Handle => "self.as_obj()",
            Receiver::Enum => {
                out.push_str("let this = self.constant(cx)?;\n");
                "this.as_obj()"
            }
            Receiver::None => "&JObject::null()",
        }
    }
}

fn cache_slot(member: &ApiMember) -> String {
    format!("cache_{}", member.rust)
}

/// A `final` object field can be cached in its handle.
fn memoized(types: &Types, class: &ApiClass, member: &ApiMember) -> bool {
    if member.kind != Kind::Field
        || !matches!(class.kind, ClassKind::Handle)
        || member.is_static
        || member.setter
        || member.element.is_some()
        || !member.is_final()
    {
        return false;
    }
    let ty = types.rtype(&parse_types(&member.descriptor)[0]);
    matches!(ty, RType::Handle(_) | RType::Object)
}

/// A `static final` object is read once per session.
fn constant(types: &Types, member: &ApiMember) -> bool {
    if member.kind != Kind::Field
        || !member.is_static
        || member.setter
        || member.nullable
        || !member.is_final()
    {
        return false;
    }
    let ty = types.rtype(&parse_types(&member.descriptor)[0]);
    matches!(ty, RType::Handle(_) | RType::Object)
}

fn param_names(member: &ApiMember, params: &[RType], label: &str) -> Result<Vec<String>, String> {
    if let Some(names) = &member.params {
        if names.len() != params.len() {
            return Err(format!(
                "{label}: `params` names {} parameters, the descriptor has {}",
                names.len(),
                params.len()
            ));
        }
        return Ok(names.iter().map(|name| snake_case(name)).collect());
    }
    let base: Vec<String> = params
        .iter()
        .map(|ty| {
            if params.len() > 1 && matches!(ty, RType::Prim(_)) {
                String::new()
            } else {
                ty.param_name()
            }
        })
        .collect();
    Ok(base
        .iter()
        .enumerate()
        .map(|(i, name)| {
            if name.is_empty() {
                format!("arg{i}")
            } else if base.iter().filter(|other| *other == name).count() > 1 {
                format!("{name}{}", i + 1)
            } else {
                name.clone()
            }
        })
        .collect())
}

fn emit_member(
    out: &mut String,
    model: &Model,
    types: &Types,
    class: &ApiClass,
    member: &ApiMember,
) -> Result<(), String> {
    let label = format!("{}.{}", class.rust, member.java);
    let (params, ret): (Vec<JType>, Option<JType>) = match member.kind {
        Kind::Field => (Vec::new(), Some(parse_types(&member.descriptor).remove(0))),
        Kind::Constructor => (method_types(&member.descriptor).0, None),
        Kind::Method => {
            let (params, ret) = method_types(&member.descriptor);
            (params, (ret != JType::Prim('V')).then_some(ret))
        }
    };
    let params: Vec<RType> = params.iter().map(|ty| types.param_rtype(ty)).collect();
    let ret: Option<RType> = ret.map(|ty| types.rtype(&ty));
    let receiver = if member.is_static || member.kind == Kind::Constructor {
        Receiver::None
    } else if matches!(class.kind, ClassKind::Enum(_)) {
        Receiver::Enum
    } else {
        Receiver::Handle
    };
    let names = param_names(member, &params, &label)?;
    let result_ty = match member.kind {
        Kind::Constructor => "Self".to_string(),
        _ => result_type(types, member, &ret, &label)?,
    };

    let all_params = std::iter::once(receiver.param().to_string())
        .chain(
            names
                .iter()
                .zip(&params)
                .map(|(name, ty)| format!("{name}: {}", ty.param())),
        )
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join(", ");
    let shim_args = std::iter::once(if receiver == Receiver::None {
        ""
    } else {
        "self"
    })
    .chain(names.iter().map(String::as_str))
    .filter(|part| !part.is_empty())
    .collect::<Vec<_>>()
    .join(", ");

    member_doc(out, model, class, member);
    let _ = writeln!(
        out,
        "pub fn {}({all_params}) -> Result<{result_ty}> {{",
        member.rust
    );

    let memo = memoized(types, class, member);
    if memo {
        let slot = cache_slot(member);
        let ty = ret.as_ref().unwrap().result();
        if member.nullable {
            let _ = writeln!(
                out,
                "if let Some(cached) = self.{slot}.get() {{ return Ok(cached.clone().map(|object| unsafe {{ {ty}::from_object_unchecked(object) }})); }}"
            );
        } else {
            let _ = writeln!(
                out,
                "if let Some(cached) = self.{slot}.get() {{ return Ok(unsafe {{ {ty}::from_object_unchecked(cached.clone()) }}); }}"
            );
        }
    }

    let shim = |function: &str| format!("crate::shims::{function}({shim_args})");
    let direct = emit_target(
        out,
        model,
        member,
        &label,
        member.kind == Kind::Field,
        Some(&shim),
    )?;
    if direct {
        out.push_str("let cx = &mut crate::cx()?;\n");
        let this = receiver.object(out);
        let args: Vec<String> = names
            .iter()
            .zip(&params)
            .enumerate()
            .map(|(index, (name, ty))| argument(out, ty, name, index))
            .collect();
        if !args.is_empty() {
            let _ = writeln!(out, "let args = [{}];", args.join(", "));
        }
        let args = if args.is_empty() { "&[]" } else { "&args" };

        match member.kind {
            Kind::Constructor => {
                let _ = writeln!(out, "let object = cx.construct(target, {args})?;");
                let _ = writeln!(out, "unsafe {{ cx.object::<Self>(object, {label:?}) }}");
            }
            Kind::Field if constant(types, member) => {
                let ty = ret.as_ref().unwrap().result();
                let _ = writeln!(out, "let global = cx.constant(target, {label:?})?;");
                let _ = writeln!(
                    out,
                    "Ok(unsafe {{ {ty}::from_object_unchecked(Object::new(global)) }})"
                );
            }
            Kind::Field => {
                let _ = writeln!(out, "let value = cx.get(target, {this})?;");
                let convert = result(types, member, &ret, &label)?;
                if memo {
                    let slot = cache_slot(member);
                    let _ = writeln!(out, "let result = {convert}?;");
                    if member.nullable {
                        let _ = writeln!(
                            out,
                            "let _ = self.{slot}.set(result.as_ref().map(|value| value.as_object().clone()));"
                        );
                    } else {
                        let _ =
                            writeln!(out, "let _ = self.{slot}.set(result.as_object().clone());");
                    }
                    out.push_str("Ok(result)\n");
                } else {
                    let _ = writeln!(out, "{convert}");
                }
            }
            Kind::Method => {
                let _ = writeln!(out, "let value = cx.call(target, {this}, {args})?;");
                let convert = result(types, member, &ret, &label)?;
                let _ = writeln!(out, "{convert}");
            }
        }
    }
    out.push_str("}\n\n");
    if member.setter {
        emit_setter(out, model, types, member, receiver, &label)?;
    }
    Ok(())
}

fn emit_setter(
    out: &mut String,
    model: &Model,
    types: &Types,
    member: &ApiMember,
    receiver: Receiver,
    label: &str,
) -> Result<(), String> {
    let ty = types.rtype(&parse_types(&member.descriptor)[0]);
    let params = [
        receiver.param().to_string(),
        format!("value: {}", ty.param()),
    ]
    .into_iter()
    .filter(|part| !part.is_empty())
    .collect::<Vec<_>>()
    .join(", ");
    let _ = writeln!(out, "pub fn set_{}({params}) -> Result<()> {{", member.rust);
    if emit_target(out, model, member, label, true, None)? {
        out.push_str("let cx = &mut crate::cx()?;\n");
        let this = receiver.object(out);
        let value = argument(out, &ty, "value", 0);
        let value = match ty {
            RType::Prim(_) => "JValue::from(value)".to_string(),
            RType::Handle(_) | RType::Object => "JValue::Object(value.as_obj())".to_string(),
            RType::Enum(_) => "JValue::Object(a0.as_obj())".to_string(),
            // A string or value argument is a prepared `jvalue`.
            _ => format!("JValue::Object(unsafe {{ &JObject::from_raw({value}.l) }})"),
        };
        let _ = writeln!(out, "cx.set(target, {this}, {value})");
    }
    out.push_str("}\n\n");
    Ok(())
}

fn emit_handle(
    out: &mut String,
    model: &Model,
    types: &Types,
    class: &ApiClass,
) -> Result<(), String> {
    let rust = &class.rust;
    let parent = match &class.parent {
        Some(parent) => types.classes[parent.as_str()].rust.clone(),
        None => "Object".to_string(),
    };
    let caches: Vec<&ApiMember> = class
        .members
        .iter()
        .filter(|member| memoized(types, class, member))
        .collect();

    class_doc(out, model, class);
    let _ = writeln!(
        out,
        "#[derive(Clone, Debug)]\npub struct {rust} {{\nbase: {parent},"
    );
    for member in &caches {
        let slot = cache_slot(member);
        let ty = if member.nullable {
            "Option<Object>"
        } else {
            "Object"
        };
        let _ = writeln!(out, "{slot}: OnceLock<{ty}>,");
    }
    out.push_str("}\n\n");

    let _ = writeln!(
        out,
        "impl std::ops::Deref for {rust} {{\ntype Target = {parent};\nfn deref(&self) -> &{parent} {{\n&self.base\n}}\n}}\n"
    );
    let _ = writeln!(
        out,
        "impl From<{rust}> for {parent} {{\nfn from(value: {rust}) -> {parent} {{\nvalue.base\n}}\n}}\n"
    );
    emit_java_type(out, model, class);
    let inits: String = caches
        .iter()
        .map(|member| format!(", {}: OnceLock::new()", cache_slot(member)))
        .collect();
    let _ = writeln!(
        out,
        "impl JavaClass for {rust} {{\n\
         unsafe fn from_object_unchecked(object: Object) -> Self {{\n\
         {rust} {{ base: unsafe {{ <{parent} as JavaClass>::from_object_unchecked(object) }}{inits} }}\n\
         }}\n\n\
         fn as_object(&self) -> &Object {{\nself.base.as_object()\n}}\n}}\n"
    );

    let _ = writeln!(out, "impl {rust} {{");
    for member in &class.members {
        emit_member(out, model, types, class, member)?;
    }
    out.push_str("}\n\n");
    Ok(())
}

fn variant_name(constant: &str) -> String {
    constant
        .split('_')
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            match chars.next() {
                Some(first) => first
                    .to_uppercase()
                    .chain(chars.flat_map(char::to_lowercase))
                    .collect(),
                None => String::new(),
            }
        })
        .collect()
}

fn emit_enum(
    out: &mut String,
    model: &Model,
    types: &Types,
    class: &ApiClass,
    constants: &[ApiMember],
) -> Result<(), String> {
    let rust = &class.rust;
    let variants: Vec<String> = constants.iter().map(|c| variant_name(&c.java)).collect();

    class_doc(out, model, class);
    let _ = writeln!(
        out,
        "#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]\npub enum {rust} {{"
    );
    for variant in &variants {
        let _ = writeln!(out, "{variant},");
    }
    out.push_str("}\n\n");
    emit_java_type(out, model, class);

    let _ = writeln!(out, "impl {rust} {{");
    let _ = writeln!(
        out,
        "pub const ALL: [{rust}; {}] = [{}];\n",
        variants.len(),
        variants
            .iter()
            .map(|v| format!("{rust}::{v}"))
            .collect::<Vec<_>>()
            .join(", ")
    );
    out.push_str(
        "pub fn to_object(self) -> Result<Object> {\nlet cx = &mut crate::cx()?;\nOk(Object::new(self.constant(cx)?))\n}\n\n",
    );
    out.push_str(
        "pub fn from_object(object: &Object) -> Result<Self> {\nlet cx = &mut crate::cx()?;\nSelf::from_java(cx, object.as_obj())\n}\n\n",
    );
    let _ = writeln!(
        out,
        "pub(crate) fn from_java(cx: &mut Cx<'_>, object: &JObject<'_>) -> Result<Self> {{\n\
         for variant in Self::ALL {{\n\
         if let Ok(constant) = variant.constant(cx) {{\n\
         if cx.same(object, constant.as_obj())? {{\nreturn Ok(variant);\n}}\n}}\n}}\n\
         Err(Error::UnknownConstant {{ class: {:?} }})\n}}\n",
        class.name
    );
    out.push_str(
        "pub(crate) fn constant(self, cx: &mut Cx<'_>) -> Result<GlobalRef> {\nmatch self {\n",
    );
    for (variant, constant) in variants.iter().zip(constants) {
        let label = format!("{rust}.{}", constant.java);
        let _ = writeln!(out, "{rust}::{variant} => {{");
        if emit_target(out, model, constant, &label, true, None)? {
            let _ = writeln!(out, "cx.constant(target, {label:?})");
        }
        out.push_str("}\n");
    }
    out.push_str("}\n}\n\n");
    for member in &class.members {
        emit_member(out, model, types, class, member)?;
    }
    out.push_str("}\n\n");
    Ok(())
}

fn emit_value(
    out: &mut String,
    model: &Model,
    types: &Types,
    class: &ApiClass,
    components: &[usize],
) -> Result<(), String> {
    let rust = &class.rust;
    let fields: Vec<(String, RType, &ApiMember)> = components
        .iter()
        .map(|&index| {
            let member = &class.members[index];
            let ty = match member.kind {
                Kind::Field => parse_types(&member.descriptor).remove(0),
                _ => method_types(&member.descriptor).1,
            };
            let name = member
                .java
                .strip_prefix("get")
                .filter(|rest| rest.starts_with(char::is_uppercase))
                .unwrap_or(&member.java);
            (snake_case(name), types.rtype(&ty), member)
        })
        .collect();
    for (name, ty, _) in &fields {
        if !matches!(ty, RType::Prim(_) | RType::Value(_) | RType::Enum(_)) {
            return Err(format!(
                "{rust}.{name}: value components are primitives, values or enums"
            ));
        }
    }
    let component_types: Vec<RType> = fields.iter().map(|(_, ty, _)| ty.clone()).collect();
    let constructor = class
        .members
        .iter()
        .find(|member| {
            member.kind == Kind::Constructor
                && method_types(&member.descriptor)
                    .0
                    .iter()
                    .map(|ty| types.rtype(ty))
                    .collect::<Vec<_>>()
                    == component_types
        })
        .ok_or_else(|| format!("{rust}: no constructor takes its components in order"))?;

    let integral = fields.iter().all(|(_, ty, _)| {
        matches!(
            ty,
            RType::Prim('Z' | 'B' | 'C' | 'S' | 'I' | 'J') | RType::Enum(_)
        )
    });
    class_doc(out, model, class);
    let derives = if integral {
        "Debug, Clone, Copy, PartialEq, Eq, Hash"
    } else {
        "Debug, Clone, Copy, PartialEq"
    };
    let _ = writeln!(out, "#[derive({derives})]\npub struct {rust} {{");
    for (name, ty, _) in &fields {
        let _ = writeln!(out, "pub {name}: {},", ty.result());
    }
    out.push_str("}\n\n");
    emit_java_type(out, model, class);

    let _ = writeln!(out, "impl {rust} {{");
    let params = fields
        .iter()
        .map(|(name, ty, _)| format!("{name}: {}", ty.result()))
        .collect::<Vec<_>>()
        .join(", ");
    let names = fields
        .iter()
        .map(|(name, _, _)| name.as_str())
        .collect::<Vec<_>>()
        .join(", ");
    let _ = writeln!(
        out,
        "pub const fn new({params}) -> {rust} {{\n{rust} {{ {names} }}\n}}\n"
    );
    let _ = writeln!(
        out,
        "pub fn from_object(object: &Object) -> Result<Self> {{\nobject.expect::<Self>({:?})?;\nlet cx = &mut crate::cx()?;\nSelf::read(cx, object.as_obj())\n}}\n",
        format!("{rust}::from_object")
    );
    let _ = writeln!(
        out,
        "pub fn to_object(&self) -> Result<Object> {{\nlet cx = &mut crate::cx()?;\nlet object = self.to_local(cx)?;\nunsafe {{ cx.object::<Object>(object, {:?}) }}\n}}\n",
        format!("{rust}::to_object")
    );

    out.push_str("pub(crate) fn read(cx: &mut Cx<'_>, object: &JObject<'_>) -> Result<Self> {\n");
    for (name, ty, member) in &fields {
        let label = format!("{rust}.{}", member.java);
        let field = member.kind == Kind::Field;
        let _ = writeln!(out, "let {name} = {{");
        emit_target(out, model, member, &label, field, None)?;
        if field {
            out.push_str("let value = cx.get(target, object)?;\n");
        } else {
            out.push_str("let value = cx.call(target, object, &[])?;\n");
        }
        let convert = match ty {
            RType::Prim(c) => format!("value.{}()?", accessor(*c)),
            _ => format!("{}?", object_result(ty, "value.l()?", &label, false)),
        };
        let _ = writeln!(out, "{convert}\n}};");
    }
    let _ = writeln!(out, "Ok({rust} {{ {names} }})\n}}\n");

    out.push_str("pub(crate) fn to_local<'l>(&self, cx: &mut Cx<'l>) -> Result<JObject<'l>> {\n");
    let label = format!("{rust}.<init>");
    emit_target(out, model, constructor, &label, false, None)?;
    let args: Vec<String> = fields
        .iter()
        .enumerate()
        .map(|(index, (name, ty, _))| argument(out, ty, &format!("self.{name}"), index))
        .collect();
    let _ = writeln!(out, "let args = [{}];", args.join(", "));
    out.push_str("cx.construct(target, &args)\n}\n\n");

    for member in &class.members {
        if member.is_static {
            emit_member(out, model, types, class, member)?;
        }
    }
    out.push_str("}\n\n");
    Ok(())
}

pub fn bindings(model: &Model) -> Result<String, String> {
    let types = Types::new(model);
    let mut out = String::from(HEADER);
    out.push_str(
        "\n#![allow(unused_variables, unused_unsafe, unreachable_code, clippy::all, clippy::pedantic)]\n\n\
         use std::sync::OnceLock;\n\n\
         use jni::objects::{GlobalRef, JObject, JValue};\n\
         use jni::signature::{Primitive, ReturnType};\n\
         use mc_runtime::{Cx, Error, Field, JavaClass, JavaType, Method, MinecraftVersion, Object, Result};\n\n",
    );
    out.push_str("/// Every supported version: id, parsed form, binding group.\n");
    out.push_str("pub(crate) static VERSIONS: &[(&str, MinecraftVersion, usize)] = &[\n");
    for ((id, parsed), group) in model.versions.iter().zip(&model.groups) {
        let _ = writeln!(
            out,
            "({id:?}, MinecraftVersion::new({}, {}, {}), {group}),",
            parsed.major, parsed.minor, parsed.patch
        );
    }
    out.push_str("];\n\n");
    for class in &model.classes {
        match &class.kind {
            ClassKind::Handle => emit_handle(&mut out, model, &types, class)?,
            ClassKind::Enum(constants) => emit_enum(&mut out, model, &types, class, constants)?,
            ClassKind::Value(components) => emit_value(&mut out, model, &types, class, components)?,
        }
    }
    Ok(out)
}

pub fn supported(model: &Model) -> String {
    let mut out = String::from(HEADER);
    out.push_str(
        "\n/// One per dump in `mc-data/dumps/`; any other version is refused unless forced.\n",
    );
    out.push_str("pub const SUPPORTED_VERSIONS: &[&str] = &[");
    let ids: Vec<String> = model
        .versions
        .iter()
        .map(|(id, _)| format!("{id:?}"))
        .collect();
    out.push_str(&ids.join(", "));
    out.push_str("];\n");
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn descriptors_split_into_types() {
        let (params, ret) = method_types("(ILjava/lang/String;[[D[Lx/Y;Z)V");
        assert_eq!(
            params,
            [
                JType::Prim('I'),
                JType::Class("java/lang/String".into()),
                JType::Array,
                JType::Array,
                JType::Prim('Z')
            ]
        );
        assert_eq!(ret, JType::Prim('V'));
        let (params, ret) = method_types("()Lnet/minecraft/client/Camera;");
        assert!(params.is_empty());
        assert_eq!(ret, JType::Class("net/minecraft/client/Camera".into()));
    }

    #[test]
    fn enum_constants_become_camel_case_variants() {
        assert_eq!(variant_name("MAIN_HAND"), "MainHand");
        assert_eq!(variant_name("UP"), "Up");
        assert_eq!(variant_name("QUICK_MOVE"), "QuickMove");
    }
}
